logic:
// LineGankerPlan::update(&mut self, _version, _rnd, player, data, goal_data, _positioning_score, _debug)
// 반환 void. _version/_rnd/_positioning_score/_debug 는 본문 미참조.

team = player.info.team                      // +0x930, 직후 <2 바운드체크
pos  = player.info.position.as_index()       // +0x9c0 (entity.rs:580)
champ = data.cache.player_champion[team][pos].unwrap()   // ganker.rs:43, None 이면 unwrap_failed 패닉

// ---- 1단계: 자기 체력 게이트 (ganker.rs:44,47) ----
hp_ratio = champ.hp * 100 / champ.stat_cached.hp   // max_hp==0 이면 div-by-zero 패닉
if hp_ratio < 41 {
    self.chats.push(Chat::Cancel(CancelReason::LowHpSelf))   // :48  tag=17, payload byte=0
    self.phase = LineGankerPhase::Cancel                     // self+0x29 = 8
    return
}

// ---- 2단계: 목표 부시 결정 = self.target_bush_v30(player, data) 를 인라인 (ganker.rs:248~305) ----
line = self.line                              // self+0x28  0=Top 1=Mid 2=Bottom
// AbstractGameWithCache::tower(line, team)  (simulation.rs:1822)
//   t1 = cache.[top|mid|bottom]_tower [team]   (cache + 0x180 + line*0x20 + team*8)
//   t2 = cache.[top|mid|bottom]_tower2[team]   (cache + 0x190 + line*0x20 + team*8)
//   tower = t1.or(t2)      // 앞선(전방) 타워가 살아있으면 그것, 아니면 2차타워
tower = ...

if tower.is_none() {                          // :250  해당 라인 타워 전멸
    bush = match line {                       // :251
        Top    => if team==0 {2}  else {16},  // :252
        Mid    => if team==0 {4}  else {17},  // :253
        Bottom => if team==0 {9}  else {21},  // :254
    }
} else {
    t = tower.unwrap()                        // :258
    is_tower = (t.ty 판별자 == 2)             // Entity+0x68, EntityType::Tower
    second   = (t.ty.Tower.ty > 4)            // Entity+0x128, TowerType::{Top2,Mid2,Bottom2}
    match line {                              // :261
      Top => {                                // :263
        if !is_tower { unreachable!() }       // :274 ("internal error: entered unreachable code")
        if second                        { bush = if team==0 {3} else {6} }   // :265
        else if t.ty.Tower.nearest_enemy.is_some()   // :267  Entity+0x88
                                         { bush = if team==0 {6} else {3} }   // :268
        else                             { bush = if team==0 {3} else {6} }   // :270
      }
      Mid => {
        if is_tower && second {                                   // :278
            if is_top_side(ctx, champ.x, champ.y) { bush = if team==0 {13} else {18} }  // :282
            else                                  { bush = if team==0 {8}  else {12} }  // :280
        } else {                                                  // 타워가 아니거나 1차타워
            bush = if is_top_side(ctx, champ.x, champ.y) {14} else {11}   // :285  team 무관
        }
      }
      Bottom => {                             // :293
        if !is_tower { unreachable!() }       // :304
        if second                        { bush = if team==0 {15} else {20} }  // :295
        else if t.ty.Tower.nearest_enemy.is_some()                             // :297
                                         { bush = if team==0 {20} else {15} }  // :298
        else                             { bush = if team==0 {15} else {20} }  // :300
      }
    }
}

// is_top_side(context, x, y)  — game-core\src\simulation\map_regions.rs:21
//   ry = context.setting.height - y      // GameSetting+0x12c0
//   return ry < x                        // :24  (미드 대각선 기준 위쪽/아래쪽)

// ---- 3단계: 챔프가 그 부시에 실제로 서 있는가 (ganker.rs:55,56) ----
champ_bush = data.context.map.bushes[ clamp(champ.y/32000, 0, 29) ]
                                    [ clamp(champ.x/32000, 0, 29) ]   // MapDef+0x1c98, [30][30] u64
if champ_bush != bush { return }             // :56  아직 목표 부시에 없음 → 아무것도 안 함

// ---- 4단계: 라인에 적이 남아 있나 (ganker.rs:57) ----
if goal_data.has_near_line_enemy(line, map) { return }   // 적이 아직 근처 → 갱 유지

self.chats.push(Chat::Cancel(CancelReason::TargetMissing))   // :58  tag=17, payload byte=2
self.phase = LineGankerPhase::Cancel                         // self+0x29 = 8

// 요약: 취소 사유는 딱 2가지 — (a) 내 HP<41% = LowHpSelf, (b) 매복 부시 도착 후 라인에 적 없음 = TargetMissing.
// 그 외 모든 경로는 조용히 return(플랜 유지). 결과는 chats 큐와 phase 두 곳에만 남는다.
